head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40212";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_zip_form = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil40212.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_3_onsubmit
 * @description form_3 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.form_3_onsubmit = async function(e){
    try {
        await scwin.goZipCode();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40212.form_3_onsubmit' }); }
};

/**
 * @method
 * @name btn_goZipCode_onclick
 * @description 「검 색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goZipCode_onclick = async function(e){
    try {
        await scwin.goZipCode()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40212.btn_goZipCode_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40212.btn_window_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_goZipCode
 * @description go Zip Code 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goZipCode = async function () {
    const sbmOptions = {
        id: "tx_goZipCode",
        method: "post",
        action: "/common/zipList.do?method=searchZipList",
        ref: "dma_goZipCodeReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} zipCode1 zipCode1
 * @param {*} zipCode2 zipCode2
 * @param {*} address address
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setZipCode = async function (zipCode1, zipCode2, address) {
    try {
        (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).setZipCode === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).setZipCode(zipCode1, zipCode2, address) : void 0), $c.win.closePopup([zipCode1, zipCode2, address]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil40212' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n");
    }
};

/**
 * @method
 * @name checkValues
 * @description check Values 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValues = async function () {
    if ($c.util.getComponent('ipt_searchWord').getValue().length === 0) {
        await $c.win.alert('검색할 지역을 입력해 주세요.');
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name goZipCode
 * @description go Zip Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goZipCode = async function () {
    if (await scwin.checkValues() === true) {
        scwin.form_zip_form.target = 'iframe';
        scwin.form_zip_form.action = '/common/zipList.do?method=searchZipList';
        await scwin.tx_goZipCode();
    } else {
        $c.util.getComponent("ipt_searchWord").focus();
    }
};
